WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CAMBIO_DE_MOTOR' AND v.numero=1),d(t,o) AS (VALUES('MOTOR DE TRACCIÓN',1),('RESPONSABLES',2)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CAMBIO_DE_MOTOR' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),f AS (SELECT jsonb_agg(jsonb_build_object('serie_antes','','bogie',b,'coche',c,'eje',n,'serie_despues','') ORDER BY n) x FROM unnest(ARRAY['PB3','PB3','PB4','PB4','PB6','PB6','PB2','PB2','PB6','PB6','PB2','PB2','TB1','TB1','TB2','TB2','PB2','PB2','PB6','PB6','PB4','PB4','PB3','PB3']) WITH ORDINALITY a(b,n) JOIN unnest(ARRAY['MA 1','MA 1','MA 1','MA 1','MB 1','MB 1','MB 1','MB 1','MB 3','MB 3','MB 3','MB 3','R','R','R','R','MB 2','MB 2','MB 2','MB 2','MA 2','MA 2','MA 2','MA 2']) WITH ORDINALITY q(c,n) USING(n)),d(t,c,e,ty,o,cf) AS (VALUES('MOTOR DE TRACCIÓN','descripcion','Descripción:','texto',1,'{}'),('MOTOR DE TRACCIÓN','cambio_motor','CAMBIO DE MOTOR DE TRACCIÓN','tabla',2,jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','serie_antes','etiqueta','Serie Antes'),jsonb_build_object('codigo','bogie','etiqueta','Bogie'),jsonb_build_object('codigo','coche','etiqueta','Coche'),jsonb_build_object('codigo','eje','etiqueta','Eje'),jsonb_build_object('codigo','serie_despues','etiqueta','Serie Después')),'filasIniciales',(SELECT x FROM f))),('RESPONSABLES','responsable_mantenimiento','RESPONSABLE MTTO :','texto',1,'{}'),('RESPONSABLES','firma_responsable_mantenimiento','FIRMA:','firma',2,'{}'),('RESPONSABLES','responsable_01','RESPONSABLE 01:','texto',3,'{}'),('RESPONSABLES','firma_responsable_01','FIRMA:','firma',4,'{}'),('RESPONSABLES','responsable_02','RESPONSABLE 02:','texto',5,'{}'),('RESPONSABLES','firma_responsable_02','FIRMA:','firma',6,'{}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
